    diagram: { type: "linearGraph", params: { slope: -2, yIntercept: 30, xRange: [0, 12], yRange: [0, 32], xTickInterval: 2, yTickInterval: 4, gridInterval: 2, showPoints: [[2, 26], [10, 10]] } },
