    diagram: { type: "linearGraph", params: { slope: 2.5, yIntercept: -1, xRange: [-4, 4], yRange: [-6, 8], xTickInterval: 2, yTickInterval: 2, gridInterval: 1, showPoints: [[0, -1], [2, 4]], label: "c" } },
